/// <summary>
/// Base class for PricingAttribute table <c>LogisticsPostalAddress</c>.
/// </summary>
internal abstract class GUPPricingAttributeLogisticsPostalAddress extends GUPAbstractPricingAttribute implements GUPIPricingAttribute
{
}

Method.Source:
    protected LogisticsPostalAddress getTableRecord(Common _pricingObject)
    {
        SalesTable             salesTable = _pricingObject as SalesTable;
        LogisticsPostalAddress logisticsPostalAddress;

        if (salesTable)
        {
            logisticsPostalAddress = LogisticsPostalAddress::findByLocation(salesTable.custTable_CustAccount().DirPartyTable_FK().PrimaryAddressLocation);
        }

        return logisticsPostalAddress;
    }

    protected QueryBuildDataSource getQueryBuildDatasource(Query _query, Map _qbdsMap = null)
    {
        QueryBuildDataSource qbds, qbds_2, qbdsRoot;

        if (_qbdsMap && _qbdsMap.exists(tableStr(CustTable)))
        {
            qbdsRoot = _qbdsMap.lookup(tableStr(CustTable));
        }
        else
        {
            qbdsRoot = _query.addDataSource(tableNum(CustTable));

            if (_qbdsMap)
            {
                _qbdsMap.insert(tableStr(CustTable), qbdsRoot);
            }
        }

        if (_qbdsMap && _qbdsMap.exists(this.getQueryBuilderDatasourceIdentifier()))
        {
            qbds = _qbdsMap.lookup(this.getQueryBuilderDatasourceIdentifier());
        }
        else
        {
            qbds = qbdsRoot.addDataSource(tableNum(DirPartyTable));
            qbds.addLink(fieldNum(CustTable, Party), fieldNum(DirPartyTable, RecId));
            qbds.joinMode(JoinMode::ExistsJoin);

            qbds_2 = qbds.addDataSource(tableNum(LogisticsPostalAddress));
            qbds_2.addLink(fieldNum(DirPartyTable, PrimaryAddressLocation), fieldNum(LogisticsPostalAddress, Location));
            qbds_2.joinMode(JoinMode::ExistsJoin);
            
            if (_qbdsMap)
            {
                _qbdsMap.insert(this.getQueryBuilderDatasourceIdentifier(), qbds_2);
            }
        }

        return qbds_2;
    }

    public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qdbsMap = null)
    {
        QueryBuildDataSource qbds;

        qbds = this.getQueryBuildDatasource(_query, _qdbsMap);
        this.setQueryBuildDatasourceRange(qbds, _value);

        return _query;
    }

public GUPPricingAttributeTableFieldPath getPath()
{
    return strFmt('%1#%2_%3$%4#%5_%6$%7#%8_%9$%10',
        tableStr(SalesTable),
        tableStr(CustTable),
        fieldStr(SalesTable, CustAccount),
        fieldStr(CustTable, AccountNum),
        tableStr(DirPartyTable),
        fieldStr(CustTable, Party),
        fieldStr(DirPartyTable, RecId),
        tableStr(LogisticsPostalAddress),
        fieldStr(DirPartyTable, PrimaryAddressLocation),
        fieldStr(LogisticsPostalAddress, Location));
}
